#pragma once
#include "Context.h"
namespace ygor::mesh_boolean::bounded { template<class T,class I>bool verify_context(const boolean_context<T,I>&c){if(!c.sources||!verify_source(c.sources->a)||!verify_source(c.sources->b)||materialize_truth_table().digest!=c.truth.digest||!verify_symbolic_policy(c.symbolic)||c.sources->digest!=c.input_digest||c.precision.source_digest!=c.input_digest)return false;canonical_writer writer;writer.u16(contract_versions::context);writer.u8(static_cast<std::uint8_t>(c.operation));writer.floating(c.options.tolerance);writer.floating(c.precision.machine_floor);for(auto byte:c.input_digest.bytes)writer.u8(byte);for(auto byte:c.truth.digest.bytes)writer.u8(byte);for(auto byte:c.symbolic.digest.bytes)writer.u8(byte);for(auto byte:c.replay_digest.bytes)writer.u8(byte);return sha256::digest(writer.bytes())==c.context_digest;} }
